CREATE OR REPLACE FUNCTION public.handle_new_organization_provisioning()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
DECLARE
  v_url      text;
  v_key      text;
  v_endpoint text;
BEGIN
  IF NEW.twilio_subaccount_sid IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT supabase_url, service_role_key
  INTO v_url, v_key
  FROM private.twilio_provisioning_config
  WHERE id = 1;

  IF v_url IS NULL OR v_url = '' OR v_key IS NULL OR v_key = '' THEN
    RAISE WARNING 'Twilio subaccount provisioning skipped for org %: private.twilio_provisioning_config not populated', NEW.id;
    RETURN NEW;
  END IF;

  v_endpoint := rtrim(v_url, '/') || '/functions/v1/provision-twilio-subaccount';

  BEGIN
    PERFORM
      net.http_post(
        url := v_endpoint,
        headers := jsonb_build_object(
          'Content-Type', 'application/json',
          'Authorization', 'Bearer ' || v_key
        ),
        body := jsonb_build_object('organization_id', NEW.id),
        timeout_milliseconds := 5000
      );
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Twilio subaccount provisioning trigger failed for org %: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_organization_seed_appointment_types()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  BEGIN
    PERFORM public.seed_default_appointment_types(NEW.id);
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'seed_default_appointment_types failed for organization %: %', NEW.id, SQLERRM;
  END;
  RETURN NEW;
END;
$function$

